    panel.querySelector('#nh-tog-ratingname').appendChild(createToggle(T.rnToggle || PANEL_T.en.rnToggle, 'shareRatingName'));
    panel.querySelector('#nh-tog-shareratings').appendChild(createToggle(T.rsToggle || PANEL_T.en.rsToggle, 'shareRatings'));
    panel.querySelector('#nh-tog-autoplay').appendChild(createToggle(T.apToggle || PANEL_T.en.apToggle, 'autoplaySeries'));
    panel.querySelector('#nh-tog-finishedtools').appendChild(createToggle(T.fdToggle || PANEL_T.en.fdToggle, 'finishedTools'));
    // Live filter over the cards: with this many settings, being able to type
    // "rating" and see only what matters is the difference between usable and not.
    (function panelSearch() {
      const box = panel.querySelector('#nh-psearch');
      const clear = panel.querySelector('#nh-psearch-x');
      const none = panel.querySelector('#nh-psearch-none');
      if (!box) return;
      const run = function () {
        const q = box.value.trim().toLowerCase();
        // searching spans BOTH tabs; the tab split comes back when the box clears
        panel.classList.toggle('nh-searching', !!q);
        const cards = panel.querySelectorAll('.nh-grid > .nh-card');
        let shown = 0;
        cards.forEach(function (c) {
          const hit = !q || c.textContent.toLowerCase().indexOf(q) !== -1;
          c.style.display = hit ? '' : 'none';
          if (hit) shown++;
        });
        // section headings only make sense while everything is visible
        panel.querySelectorAll('.nh-grid > .nh-sect').forEach(function (h) { h.style.display = q ? 'none' : ''; });
        if (none) none.style.display = (q && !shown) ? 'block' : 'none';
        if (clear) clear.style.display = q ? 'block' : 'none';
      };
      box.addEventListener('input', run);
      box.addEventListener('search', run);
      if (clear) clear.addEventListener('click', function () { box.value = ''; run(); box.focus(); });
      run();
    })();
    // The redesigned-pages toggles moved to the ADMIN tab (Pawel: only the
    // admin decides which redesigned pages the server runs) - see the
    // Administration block below.
    (function buildBookSites() {
      const host = panel.querySelector('#nh-booksites');
      if (!host) return;
      const lang = getUserLanguage().split('-')[0].toLowerCase();
      const chosen = nhBookSitesSelected().slice();
      const groups = [
        [T.bsGlobal || PANEL_T.en.bsGlobal, NH_BOOK_SITES.filter((x) => x.langs.indexOf('*') !== -1)],
        [T.bsLocal || PANEL_T.en.bsLocal, NH_BOOK_SITES.filter((x) => x.langs.indexOf(lang) !== -1)],
        [T.bsOther || PANEL_T.en.bsOther, NH_BOOK_SITES.filter((x) => x.langs.indexOf('*') === -1 && x.langs.indexOf(lang) === -1)],
      ];
      groups.forEach(function (g) {
        if (!g[1].length) return;
        const h = document.createElement('div');
        h.className = 'nh-bs-group';
        h.textContent = g[0];
        host.appendChild(h);
        const wrap = document.createElement('div');
        wrap.className = 'nh-bs-list';
        g[1].forEach(function (site) {
          const lab = document.createElement('label');
          lab.className = 'nh-bs-check';
          const cb = document.createElement('input');
          cb.type = 'checkbox';
          cb.checked = chosen.indexOf(site.id) !== -1;
          cb.addEventListener('change', function () {
            const cur = nhBookSitesSelected().slice();
            const at = cur.indexOf(site.id);
            if (cb.checked && at === -1) cur.push(site.id);
            if (!cb.checked && at !== -1) cur.splice(at, 1);
            nhSettings.bookSites = cur;
            saveSettings();
            document.querySelectorAll('.nh-bs-row').forEach(function (r) { r.dataset.sig = ''; });
          });
          const txt = document.createElement('span');
          txt.textContent = site.name;
          lab.appendChild(cb); lab.appendChild(txt);
          wrap.appendChild(lab);
        });
        host.appendChild(wrap);
      });
    })();
    (function () {
      const sel = document.createElement('select');
      sel.className = 'nh-er-select';
      const addOpt = (v, txt) => { const o = document.createElement('option'); o.value = v; o.textContent = txt; sel.appendChild(o); };
      addOpt('', T.spDefault || PANEL_T.en.spDefault);
      nhGsLibs().then((libs) => {
        if (!libs) return;
        const views = [
          ['home', T.spViewHome || PANEL_T.en.spViewHome],
          ['bookshelf', T.spViewLibrary || PANEL_T.en.spViewLibrary],
          ['series', T.spViewSeries || PANEL_T.en.spViewSeries],
          ['collections', T.spViewCollections || PANEL_T.en.spViewCollections],
          ['authors', T.spViewAuthors || PANEL_T.en.spViewAuthors]
        ];
        libs.forEach((lib) => views.forEach((v) => addOpt(v[0] + ':' + lib.id, lib.name + ' · ' + v[1])));
        if (nhSettings.startPage && sel.querySelector('option[value="' + nhSettings.startPage + '"]')) sel.value = nhSettings.startPage;
      });
      sel.addEventListener('change', () => { nhSettings.startPage = sel.value; saveSettings(); });
      panel.querySelector('#nh-sel-startpage').appendChild(sel);
      nhSelectify(sel);
    })();
    (function () {
      const sel = document.createElement('select');
      sel.className = 'nh-er-select';
      [['deck', T.scmDeck || PANEL_T.en.scmDeck], ['first', T.scmFirst || PANEL_T.en.scmFirst], ['grid', T.scmGrid || PANEL_T.en.scmGrid], ['off', T.scmOff || PANEL_T.en.scmOff]].forEach((o) => {
        const opt = document.createElement('option');
        opt.value = o[0]; opt.textContent = o[1];
        sel.appendChild(opt);
      });
      sel.value = ['deck', 'first', 'grid', 'off'].indexOf(nhSettings.seriesCoverMode) !== -1 ? nhSettings.seriesCoverMode : 'grid';
      sel.addEventListener('change', () => { nhSettings.seriesCoverMode = sel.value; saveSettings(); });
      panel.querySelector('#nh-sel-seriescover').appendChild(sel);
      nhSelectify(sel);
    })();

    const bindInput = (id, key) => {
      const el = panel.querySelector(id);
      if (nhSettings[key] !== undefined) el.value = nhSettings[key];
      el.addEventListener('input', (e) => {
        nhSettings[key] = el.type === 'number' ? parseInt(e.target.value, 10) : e.target.value;
        saveSettings(); applySettings();
      });
      return el;
    };

    bindInput('#nh-in-name', 'appName');
    bindInput('#nh-hc-key', 'hcKey');
    // The logo URL is NOT bound live like the others (#28): a value only lands
    // in the settings (and syncs to the user's other browsers) once it is empty
    // or a usable image source. Anything else just marks the field.
    const logoInput = panel.querySelector('#nh-in-logo');
    if (nhSettings.logoUrl !== undefined) logoInput.value = nhSettings.logoUrl;
    logoInput.addEventListener('input', () => {
      const raw = logoInput.value.trim();
      const ok = raw === '' ? '' : nhLogoOk(raw);
      logoInput.classList.toggle('nh-in-bad', raw !== '' && !ok);
      if (raw !== '' && !ok) return;
      nhSettings.logoUrl = ok;
      saveSettings(); applySettings();
    });

    logoInput.addEventListener('change', (e) => {
      if (e.target.value.trim() === '') {
        nhSettings.colorizeLogo = false;
        saveSettings(); applySettings();
        const colorizeTogBtn = panel.querySelector('#nh-tog-colorize button');
        if (colorizeTogBtn) colorizeTogBtn.className = 'border rounded-full flex items-center bg-primary border-black-100 justify-start';
      }
    });

    // Logo upload (admin only): browse a device image, PUT it into the /data/nh volume,
    // then point the logo at the same-origin /_nh/logo.<ext> so it renders with NO internet.
    const logoUploadRow = panel.querySelector('#nh-logo-upload-row');
    if (logoUploadRow && isUserAdmin()) {
      logoUploadRow.style.display = 'flex';
      const logoFile = panel.querySelector('#nh-in-logo-file');
      const logoStatus = panel.querySelector('#nh-logo-upload-status');
      panel.querySelector('#nh-logo-upload-btn').addEventListener('click', () => logoFile.click());
      logoFile.addEventListener('change', () => {
        const file = logoFile.files && logoFile.files[0];
        if (!file) return;
        const byMime = { 'image/png': 'png', 'image/svg+xml': 'svg', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'image/gif': 'gif', 'image/avif': 'avif', 'image/x-icon': 'ico', 'image/vnd.microsoft.icon': 'ico' };
        let ext = byMime[file.type] || (file.name.split('.').pop() || '').toLowerCase();
        if (ext === 'jpeg') ext = 'jpg';
        if (!/^(png|svg|jpg|webp|gif|avif|ico)$/.test(ext)) { logoStatus.textContent = T.logoBadType || PANEL_T.en.logoBadType; logoFile.value = ''; return; }
        if (file.size > 4 * 1024 * 1024) { logoStatus.textContent = T.logoTooBig || PANEL_T.en.logoTooBig; logoFile.value = ''; return; }
        logoStatus.textContent = '…';
        let token = '';
        try { const st = window.$nuxt.$store; token = st.getters['user/getToken'] || (st.state.user.user && (st.state.user.user.accessToken || st.state.user.user.token)) || ''; } catch (e) {}
        fetch('/_nh/data/logo.' + ext, { method: 'PUT', headers: { 'Authorization': 'Bearer ' + token }, body: file })
          .then((r) => {
            if (!r.ok) { logoStatus.textContent = T.srvErr || PANEL_T.en.srvErr; return; }
            // Cache-bust in the stored URL so the new logo shows at once and re-uploads
            // refresh too (applySettings re-asserts this exact src each tick).
            nhSettings.logoUrl = '/_nh/logo.' + ext + '?v=' + Date.now();
            logoInput.value = nhSettings.logoUrl;
            saveSettings(); applySettings();
            logoStatus.textContent = T.logoUploaded || PANEL_T.en.logoUploaded;
            setTimeout(() => { logoStatus.textContent = ''; }, 2500);
          })
          .catch(() => { logoStatus.textContent = T.srvErr || PANEL_T.en.srvErr; });
        logoFile.value = '';
      });
    }

    bindInput('#nh-in-carousel', 'carouselTiming');
